<template><section aria-label="Сохранённые поиски"><p v-if="searches.length === 0">Сохранённых поисков пока нет.</p><ul v-else><li v-for="search in searches" :key="search.id"><strong>{{ search.name }}</strong> — {{ search.text }} <label><input :checked="search.is_enabled" type="checkbox" @change="emit('toggle', search.id, !search.is_enabled)" /> Включён</label></li></ul></section></template>
<script setup lang="ts">import type { SavedSearch } from "../api/saved-searches";defineProps<{searches:SavedSearch[]}>();const emit=defineEmits<{toggle:[id:number,enabled:boolean]}>();</script>
